import { getApiOrigin, getConfiguredIrrPerUsd } from './config';

export type PaymentStatus =
  | 'CREATED'
  | 'REDIRECTED'
  | 'VERIFY_PENDING'
  | 'VERIFIED'
  | 'FAILED'
  | 'CANCELED'
  | 'FRAUD'
  | 'REQUEST_UNKNOWN';

export type PaymentConflictCode =
  | 'IDEMPOTENCY_KEY_REUSED'
  | 'PAYMENT_OUTCOME_UNKNOWN'
  | 'PAYMENT_IN_PROGRESS'
  | 'PAYMENT_ALREADY_PROCESSED';

export interface PaymentRecord {
  paymentId: string;
  amount: number;
  status: PaymentStatus;
  createdAt?: string;
  verifiedAt?: string;
  refId?: string;
}

export interface CreatePaymentPayload {
  amount: number;
  description: string;
}

export interface CreatePaymentSuccessResponse {
  success: true;
  paymentId: string;
  redirect: string;
}

export interface PaymentStatusResponse {
  success: true;
  payment: PaymentRecord;
}

export class PaymentApiError extends Error {
  public readonly status: number;
  public readonly code?: string;
  public readonly paymentId?: string;

  constructor(message: string, status: number, code?: string, paymentId?: string) {
    super(message);
    this.name = 'PaymentApiError';
    this.status = status;
    this.code = code;
    this.paymentId = paymentId;
  }
}

export interface CheckoutAttempt {
  idempotencyKey: string;
  cartKey: string;
  amount: number;
  description: string;
  paymentId?: string;
  lastStatus?: PaymentStatus;
  createdAt: string;
}

const ATTEMPT_STORAGE_KEY = 'quader_checkout_payment_attempt_v1';

/**
 * Terminal failure/canceled statuses after which a new user-initiated attempt
 * must generate a fresh idempotency key.
 */
export function isTerminalFailureStatus(status?: PaymentStatus): boolean {
  return status === 'FAILED' || status === 'CANCELED' || status === 'FRAUD';
}

/**
 * Generates a v4 UUID for the `Idempotency-Key` header using `crypto.randomUUID()` where available.
 */
export function generateIdempotencyKey(): string {
  if (typeof crypto !== 'undefined' && typeof crypto.randomUUID === 'function') {
    return crypto.randomUUID();
  }
  // Standard RFC4122 v4 fallback for environments without crypto.randomUUID
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, char => {
    const rand = (Math.random() * 16) | 0;
    const val = char === 'x' ? rand : (rand & 0x3) | 0x8;
    return val.toString(16);
  });
}

/**
 * Explicitly converts a catalog USD total into a positive integer in Iranian Rials (IRR)
 * for ZarinPal's default Rial unit. Never converts silently—callers display both values.
 */
export function convertUsdToIrr(usdAmount: number, irrPerUsd = getConfiguredIrrPerUsd()): number {
  if (!Number.isFinite(usdAmount) || usdAmount <= 0) {
    throw new Error('Checkout USD total must be greater than zero.');
  }
  const rials = Math.round(usdAmount * irrPerUsd);
  if (!Number.isInteger(rials) || rials <= 0) {
    throw new Error('Converted Rial payment amount must be a positive integer.');
  }
  return rials;
}

/**
 * Formats an integer Rial (IRR) amount for explicit display on checkout and status screens.
 */
export function formatIrrAmount(amountIrr: number): string {
  if (!Number.isFinite(amountIrr)) return '0 IRR';
  return `${Math.round(amountIrr).toLocaleString('en-US')} IRR`;
}

/**
 * Reads the persisted checkout attempt from sessionStorage.
 */
export function getStoredCheckoutAttempt(): CheckoutAttempt | null {
  if (typeof sessionStorage === 'undefined') return null;
  try {
    const raw = sessionStorage.getItem(ATTEMPT_STORAGE_KEY);
    if (!raw) return null;
    const parsed = JSON.parse(raw) as CheckoutAttempt;
    if (!parsed || typeof parsed.idempotencyKey !== 'string' || !parsed.idempotencyKey) {
      return null;
    }
    return parsed;
  } catch {
    return null;
  }
}

/**
 * Saves the current checkout attempt in sessionStorage.
 */
export function saveCheckoutAttempt(attempt: CheckoutAttempt): CheckoutAttempt {
  if (typeof sessionStorage !== 'undefined') {
    try {
      sessionStorage.setItem(ATTEMPT_STORAGE_KEY, JSON.stringify(attempt));
    } catch {}
  }
  return attempt;
}

/**
 * Clears the stored checkout attempt (called upon verified payment or explicit reset).
 */
export function clearCheckoutAttempt(): void {
  if (typeof sessionStorage !== 'undefined') {
    try {
      sessionStorage.removeItem(ATTEMPT_STORAGE_KEY);
    } catch {}
  }
}

/**
 * Returns the existing checkout attempt if it matches the current cart & amount and is not
 * in a terminal failure state, or creates and persists a single UUID idempotency key.
 */
export function getOrCreateCheckoutAttempt(params: {
  cartKey: string;
  amount: number;
  description: string;
}): CheckoutAttempt {
  const existing = getStoredCheckoutAttempt();
  if (
    existing &&
    existing.cartKey === params.cartKey &&
    existing.amount === params.amount &&
    !isTerminalFailureStatus(existing.lastStatus)
  ) {
    return existing;
  }

  const fresh: CheckoutAttempt = {
    idempotencyKey: generateIdempotencyKey(),
    cartKey: params.cartKey,
    amount: params.amount,
    description: params.description,
    createdAt: new Date().toISOString(),
  };
  return saveCheckoutAttempt(fresh);
}

/**
 * Explicitly rotates the idempotency key when the user deliberately initiates
 * a new payment attempt after a terminal failure/cancel or amount mismatch.
 */
export function startNewCheckoutAttempt(params: {
  cartKey: string;
  amount: number;
  description: string;
}): CheckoutAttempt {
  const fresh: CheckoutAttempt = {
    idempotencyKey: generateIdempotencyKey(),
    cartKey: params.cartKey,
    amount: params.amount,
    description: params.description,
    createdAt: new Date().toISOString(),
  };
  return saveCheckoutAttempt(fresh);
}

/**
 * Updates fields on the persisted checkout attempt (e.g. recording `paymentId` or `lastStatus`).
 */
export function updateStoredCheckoutAttempt(patch: Partial<CheckoutAttempt>): CheckoutAttempt | null {
  const current = getStoredCheckoutAttempt();
  if (!current) return null;
  const updated: CheckoutAttempt = { ...current, ...patch };
  return saveCheckoutAttempt(updated);
}

/**
 * Navigation helper so full-page ZarinPal redirects can be executed in the browser
 * and cleanly spied on in unit/integration tests.
 */
export const paymentNavigation = {
  redirectToGateway(url: string): void {
    if (!url || typeof url !== 'string') {
      throw new Error('Invalid gateway redirect URL.');
    }
    window.location.assign(url);
  },
};

function parseErrorPayload(data: any, fallbackStatus: number): {
  message: string;
  code?: string;
  paymentId?: string;
} {
  const code = data?.code || data?.errorCode || (typeof data?.error === 'string' && /^[A-Z_]+$/.test(data.error) ? data.error : undefined);
  const paymentId = data?.paymentId || data?.payment?.paymentId;
  const message =
    data?.message ||
    (typeof data?.error === 'string' ? data.error : undefined) ||
    `Payment request failed with status ${fallbackStatus}`;
  return { message, code, paymentId };
}

/**
 * Low-level API calls adhering strictly to the backend payment contract:
 * 1. `POST /shop/payments/create` with `credentials: "include"` and `Idempotency-Key`
 * 2. `GET /shop/payments/status/:paymentId` with `credentials: "include"`
 */
export const paymentApi = {
  async createPayment(
    payload: CreatePaymentPayload,
    idempotencyKey: string
  ): Promise<CreatePaymentSuccessResponse> {
    if (!Number.isInteger(payload.amount) || payload.amount <= 0) {
      throw new PaymentApiError('Payment amount must be a positive integer.', 400, 'INVALID_AMOUNT');
    }
    if (!payload.description || !payload.description.trim()) {
      throw new PaymentApiError('Payment description is required.', 400, 'INVALID_DESCRIPTION');
    }
    if (!idempotencyKey || !idempotencyKey.trim()) {
      throw new PaymentApiError('Idempotency-Key is required.', 400, 'MISSING_IDEMPOTENCY_KEY');
    }

    const origin = getApiOrigin();
    const res = await fetch(`${origin}/shop/payments/create`, {
      method: 'POST',
      credentials: 'include',
      headers: {
        'Content-Type': 'application/json',
        'Idempotency-Key': idempotencyKey,
      },
      body: JSON.stringify({
        amount: payload.amount,
        description: payload.description.trim(),
      }),
    });

    let data: any = null;
    try {
      data = await res.json();
    } catch {
      data = null;
    }

    if (!res.ok || !data?.success) {
      const { message, code, paymentId } = parseErrorPayload(data, res.status);
      throw new PaymentApiError(message, res.status, code, paymentId);
    }

    if (typeof data.redirect !== 'string' || !data.redirect.trim()) {
      throw new PaymentApiError(
        'Gateway redirect URL was missing from payment response.',
        502,
        'MISSING_REDIRECT',
        data.paymentId
      );
    }

    return {
      success: true,
      paymentId: String(data.paymentId || ''),
      redirect: String(data.redirect),
    };
  },

  async getPaymentStatus(paymentId: string): Promise<PaymentStatusResponse> {
    if (!paymentId || !paymentId.trim()) {
      throw new PaymentApiError('Payment ID is required to check status.', 400, 'MISSING_PAYMENT_ID');
    }

    const origin = getApiOrigin();
    const res = await fetch(
      `${origin}/shop/payments/status/${encodeURIComponent(paymentId.trim())}`,
      {
        method: 'GET',
        credentials: 'include',
        headers: {
          Accept: 'application/json',
        },
      }
    );

    let data: any = null;
    try {
      data = await res.json();
    } catch {
      data = null;
    }

    if (!res.ok || !data?.success || !data?.payment) {
      const { message, code } = parseErrorPayload(data, res.status);
      throw new PaymentApiError(message, res.status, code, paymentId);
    }

    return {
      success: true,
      payment: {
        paymentId: String(data.payment.paymentId || paymentId),
        amount: Number(data.payment.amount),
        status: data.payment.status as PaymentStatus,
        createdAt: data.payment.createdAt,
        verifiedAt: data.payment.verifiedAt,
        refId: data.payment.refId,
      },
    };
  },
};

export type CheckoutSubmissionOutcome =
  | {
      type: 'REDIRECTED';
      paymentId: string;
      redirect: string;
      idempotencyKey: string;
    }
  | {
      type: 'RECOVERED_STATUS';
      payment: PaymentRecord;
      idempotencyKey: string;
      conflictCode?: string;
    }
  | {
      type: 'CONFLICT_KEY_REUSED';
      message: string;
      idempotencyKey: string;
    }
  | {
      type: 'OUTCOME_UNKNOWN_NO_ID';
      message: string;
      idempotencyKey: string;
      code: string;
    };

/**
 * Executes a single idempotent checkout attempt and handles `409` duplicate/in-progress
 * recovery per backend specification:
 * - Reuses the exact persisted `idempotencyKey` for network retries, double-clicks, and recovery.
 * - On `409` (`PAYMENT_IN_PROGRESS`, `PAYMENT_OUTCOME_UNKNOWN`, `PAYMENT_ALREADY_PROCESSED`),
 *   queries `GET /shop/payments/status/:paymentId` when `paymentId` is available.
 * - If an in-progress attempt becomes `REDIRECTED`, retries `POST /shop/payments/create` with
 *   the SAME `idempotencyKey` to retrieve the existing redirect URL (never creating a fresh key automatically).
 */
export async function submitOrRecoverCheckoutPayment(params: {
  cartKey: string;
  amount: number;
  description: string;
  autoRedirect?: boolean;
}): Promise<CheckoutSubmissionOutcome> {
  const attempt = getOrCreateCheckoutAttempt({
    cartKey: params.cartKey,
    amount: params.amount,
    description: params.description,
  });

  try {
    const created = await paymentApi.createPayment(
      { amount: params.amount, description: params.description },
      attempt.idempotencyKey
    );

    updateStoredCheckoutAttempt({
      paymentId: created.paymentId,
      lastStatus: 'REDIRECTED',
    });

    if (params.autoRedirect !== false) {
      paymentNavigation.redirectToGateway(created.redirect);
    }

    return {
      type: 'REDIRECTED',
      paymentId: created.paymentId,
      redirect: created.redirect,
      idempotencyKey: attempt.idempotencyKey,
    };
  } catch (err) {
    if (err instanceof PaymentApiError && err.status === 409) {
      const conflictCode = err.code as PaymentConflictCode | undefined;
      const recoveryPaymentId = err.paymentId || attempt.paymentId;

      if (conflictCode === 'IDEMPOTENCY_KEY_REUSED') {
        return {
          type: 'CONFLICT_KEY_REUSED',
          message:
            err.message ||
            'The payment amount changed since this attempt started. Please start a fresh payment attempt.',
          idempotencyKey: attempt.idempotencyKey,
        };
      }

      if (recoveryPaymentId) {
        updateStoredCheckoutAttempt({ paymentId: recoveryPaymentId });
        const statusRes = await paymentApi.getPaymentStatus(recoveryPaymentId);
        const payment = statusRes.payment;
        updateStoredCheckoutAttempt({
          paymentId: payment.paymentId,
          lastStatus: payment.status,
        });

        // Spec requirement:
        // "If an in-progress attempt becomes REDIRECTED, retry the create request with the same key
        // to retrieve the existing redirect URL; never make a second attempt with a fresh key automatically."
        if (payment.status === 'REDIRECTED') {
          const retried = await paymentApi.createPayment(
            { amount: params.amount, description: params.description },
            attempt.idempotencyKey
          );
          updateStoredCheckoutAttempt({
            paymentId: retried.paymentId,
            lastStatus: 'REDIRECTED',
          });
          if (params.autoRedirect !== false) {
            paymentNavigation.redirectToGateway(retried.redirect);
          }
          return {
            type: 'REDIRECTED',
            paymentId: retried.paymentId,
            redirect: retried.redirect,
            idempotencyKey: attempt.idempotencyKey,
          };
        }

        return {
          type: 'RECOVERED_STATUS',
          payment,
          idempotencyKey: attempt.idempotencyKey,
          conflictCode,
        };
      }

      return {
        type: 'OUTCOME_UNKNOWN_NO_ID',
        message:
          err.message ||
          'A payment request with this key is already in progress or its outcome is being determined. Please wait before retrying.',
        idempotencyKey: attempt.idempotencyKey,
        code: conflictCode || 'CONFLICT',
      };
    }

    throw err;
  }
}
